import{_ as s,o as e,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"小明","description":"","frontmatter":{"title":"小明","date":"2026-11-08T00:00:00.000Z","seq":47,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/小明.md","filePath":"blogs/诗经·小雅/小明.md"}'),p={name:"blogs/诗经·小雅/小明.md"};function c(l,a,n,r,_,m){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="小明" tabindex="-1">小明 <a class="header-anchor" href="#小明" aria-label="Permalink to &quot;小明&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　小雅 · 谷风之什</p><div class="poem"><p class="poem-stanza">明明上天，照临下土。我征徂西，至于艽野。二月初吉，载离寒暑。</p><p class="poem-stanza">心之忧矣，其毒大苦。念彼共人，涕零如雨。岂不怀归？畏此罪罟！</p><p class="poem-stanza">昔我往矣，日月方除。曷云其还？岁聿云莫。念我独兮，我事孔庶。</p><p class="poem-stanza">心之忧矣，惮我不暇。念彼共人，眷眷怀顾！岂不怀归？畏此谴怒。</p><p class="poem-stanza">昔我往矣，日月方奥。曷云其还？政事愈蹙。岁聿云莫，采萧获菽。</p><p class="poem-stanza">心之忧矣，自诒伊戚。念彼共人，兴言出宿。岂不怀归？畏此反覆。</p><p class="poem-stanza">嗟尔君子，无恒安处。靖共尔位，正直是与。神之听之，式穀以女。</p><p class="poem-stanza">嗟尔君子，无恒安息。靖共尔位，好是正直。神之听之，介尔景福。</p></div>',3)])])}const u=s(p,[["render",c]]);export{d as __pageData,u as default};
